import json, re
for fn in ['resume.json','reference_manifest.json']:
    d=json.load(open(fn))
    def walk(obj, path=''):
        if isinstance(obj, dict):
            for k,v in obj.items():
                walk(v, path+'.'+k)
        elif isinstance(obj, list):
            for i,v in enumerate(obj):
                walk(v, path+f'[{i}]')
        elif isinstance(obj, str) and re.fullmatch(r'[0-9a-f]{40,80}', obj):
            valid = bool(re.fullmatch(r'[0-9a-f]{64}', obj))
            print(fn, path, len(obj), 'VALID64' if valid else 'INVALID_LEN', obj)
    walk(d)
"
